on conflict (city) do update set boundary = excluded.boundary;

create or replace function public.guard_camanava_apartment_location()
returns trigger
language plpgsql
security definer
set search_path = private, extensions, public
as $$
declare
  v_boundary extensions.geometry;
  v_location extensions.geometry;
begin
  if new.city not in ('Caloocan', 'Malabon', 'Navotas', 'Valenzuela')
    or new.province <> 'Metro Manila' then
    raise exception 'Properties can only be listed in Caloocan, Malabon, Navotas, or Valenzuela, Metro Manila.';
  end if;

  if new.latitude is null or new.longitude is null then
    raise exception 'Pin your property location within the selected CAMANAVA city.';
  end if;

  select boundary into v_boundary
  from private.camanava_city_boundaries
  where city = new.city;

  v_location := extensions.ST_SetSRID(extensions.ST_MakePoint(new.longitude, new.latitude), 4326);

  if v_boundary is null or not extensions.ST_Covers(v_boundary, v_location) then
    raise exception 'The map pin must be inside the selected CAMANAVA city (%).', new.city;
  end if;

  return new;
end;
$$;

revoke all on function public.guard_camanava_apartment_location() from public;

drop trigger if exists guard_camanava_apartment_location on public.apartments;
create trigger guard_camanava_apartment_location
  before insert or update of city, province, latitude, longitude on public.apartments
  for each row
  execute function public.guard_camanava_apartment_location();
